import { getDivergentPointIndex } from './get-divergent-point-index.js';
import { LEGEND_VARIANTS } from '../constants.js';
import { Variant } from '../types/range-legend.internal.js';
import { RangeItem } from '../types/range-legend.js';

export const getVariant = (items: RangeItem[]): Variant => {
  if (getDivergentPointIndex(items) !== -1) {
    return LEGEND_VARIANTS.DIVERGENT;
  }
  const hasSameSizedSegments = items.every(
    (item) => item.to - item.from === items[0].to - items[0].from,
  );

  if (hasSameSizedSegments) {
    return LEGEND_VARIANTS.SEQUENTIAL;
  }

  return LEGEND_VARIANTS.RANGED;
};
